from dataclasses import dataclass, field

@dataclass
class Student:
    name: str
    grades: list = field(default_factory=list)

    def average(self):
        return sum(self.grades) / len(self.grades) if self.grades else 0

class GradeBook:
    def __init__(self):
        self.students = []

    def add_student(self, student):
        self.students.append(student)

    def get_student(self, name):
        for s in self.students:
            if s.name == name:
                return s
        return None

    def class_average(self):
        if not self.students:
            return 0
        return sum(s.average() for s in self.students) / len(self.students)

    def top_student(self):
        if not self.students:
            return None
        return max(self.students, key=lambda s: s.average())

book = GradeBook()
book.add_student(Student('Alice', [90, 85]))
book.add_student(Student('Bob', [70, 80]))

print(book.get_student('Alice'))
print(book.get_student('Zed'))
print(book.class_average())

