        name = input('Student name: ')
        student = book.get_student(name)
        if student is None:
            print('No such student')
        else:
            student.grades.append(float(input('Grade: ')))
            print('Grade added')
    elif choice == '3':
        for s in book.students:
            print(f'{s.name:<10} {s.average():.1f}')
        print(f'Class average: {book.class_average():.1f}')
    elif choice == '4':
        book.save_to_csv('gradebook.csv')
        print('Saved. Bye.')
        break
    else:
        print('Unknown option')

